#!/usr/bin/env node
import { writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const args = process.argv.slice(2);
const stdinBuffer = [];

process.stdin.on('data', (chunk) => stdinBuffer.push(chunk));
process.stdin.on('end', () => {
	const flag = args[0] || 'success';

	if (flag === '--timeout') {
		setTimeout(() => {}, 60000);
		return;
	}

	if (flag === '--fail') {
		process.stderr.write('Error: something went wrong\n');
		process.exit(1);
	}

	if (flag === '--artifact') {
		const artifactDir = args[1] || tmpdir();
		const artifactFile = args[2] || 'plan.md';
		if (!existsSync(artifactDir)) mkdirSync(artifactDir, { recursive: true });
		writeFileSync(join(artifactDir, artifactFile), '# Plan\n\nGenerated by fake AI CLI\n');
	}

	process.stdout.write('AI session completed successfully\n');
	process.exit(0);
});
